import{z as i,x as n,o as l,c as d,q as r,j as t,D as B,d as a,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"模型坍缩的实证","description":"","frontmatter":{"title":"模型坍缩的实证","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/model-collapse-empirics.md","filePath":"llm/model-collapse-empirics.md","lastUpdated":1791063341000}'),m={name:"llm/model-collapse-empirics.md"};function C(p,E,h,F,u,D){const A=n("Mermaid");return l(),d("div",null,[E[2]||(E[2]=r('<h1 id="模型坍缩的实证" tabindex="-1">模型坍缩的实证 <a class="header-anchor" href="#模型坍缩的实证" aria-label="Permalink to &quot;模型坍缩的实证&quot;">​</a></h1><div class="epigraph"><p>递归自食的模型不是先变笨，是先失去尾部：稀有但正确的表达最先消失，剩下的分布一代比一代窄。</p><footer>—— Shumailov 等，AI models collapse when trained on recursively generated data，Nature 2024</footer></div><p><a href="/llm/data-flywheel-stop">上一课</a>把「何时停」写成了可否决的判据。本课补上判据背后的事实依据：递归用合成数据训练自己会发生什么。实证文献给的是两条不对称的结论——替换式递归会坍缩（尾部先丢、熵收缩），累积式与回混真实数据则可以不坍缩。「所有合成数据都危险」与「我们没观察到崩坏」都是错读。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shumailov 等人 2024 年发表于 Nature 的实验把「生成—训练」循环跑了多代，覆盖高斯、数字与文本三类任务，每代用上一代模型的输出替换原始分布训练。三条实证结论：尾部先丢——分布两端的低密度样本（罕见词、极端值、少见解法）在数代内最先消失；熵收缩——输出的多样性与熵逐代下降；退化在数代内近乎不可逆——其文本实验到第九代前后，输出已接近无意义（原文实验口径）。Alemohammad 等人对自消费生成模型的同期工作得到同构结论：完全自食的生成器收敛到远离真实分布的退化态。</p><p><span class="marginnote">替换式与累积式的差别在工程上就是数据湖删不删旧数据：每代只用最新合成数据重训是替换式；追加进数据湖再训是累积式。前者才会坍缩。</span></p><p><span class="marginnote">术语翻译：熵在这里就是「输出多样程度」的度量——模型下一句话的可选范围有多宽。熵收缩不是变笨，而是变窄：翻来覆去只会说少数几种「安全」的说法，稀有但正确的表达先从菜单上消失。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="什么条件下不坍缩" tabindex="-1">什么条件下不坍缩 <a class="header-anchor" href="#什么条件下不坍缩" aria-label="Permalink to &quot;什么条件下不坍缩&quot;">​</a></h3>',9)),(l(),t(s,null,{default:B(()=>[o(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20GEN%5B%22%E7%AC%AC%20t%20%E4%BB%A3%E6%A8%A1%E5%9E%8B%E7%94%9F%E6%88%90%22%5D%20--%3E%20FIL%5B%22%E8%BF%87%E6%BB%A4%E4%B8%8E%E8%B4%A8%E9%87%8F%E7%AD%9B%E9%80%89%22%5D%0A%20%20FIL%20--%3E%20MIX%7B%22%E6%95%B0%E6%8D%AE%E5%A6%82%E4%BD%95%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E4%BB%A3%EF%BC%9F%22%7D%0A%20%20MIX%20--%3E%7C%E6%9B%BF%E6%8D%A2%E5%BC%8F%7C%20COLL%5B%22%E5%9D%8D%E7%BC%A9%EF%BC%9A%E5%B0%BE%E9%83%A8%E5%85%88%E4%B8%A2%EF%BC%8C%E7%86%B5%E6%94%B6%E7%BC%A9%22%5D%0A%20%20MIX%20--%3E%7C%E7%B4%AF%E7%A7%AF%E5%BC%8F%7C%20ACC%5B%22%E4%BF%9D%E7%95%99%E5%85%A8%E9%83%A8%E5%8E%86%E5%8F%B2%EF%BC%9A%E8%BF%91%E4%BC%BC%E5%B9%B3%E7%A8%B3%22%5D%0A%20%20MIX%20--%3E%7C%E5%9B%9E%E6%B7%B7%E7%9C%9F%E5%AE%9E%7C%20ANCH%5B%22%E6%8E%BA%E5%85%A5%E7%9C%9F%E5%AE%9E%E6%95%B0%E6%8D%AE%EF%BC%9A%E5%A4%A7%E5%B9%85%E6%8E%A8%E8%BF%9F%22%5D%0A%20%20COLL%20--%3E%20NEXT%5B%22%E7%AC%AC%20t%2B1%20%E4%BB%A3%22%5D%0A%20%20ACC%20--%3E%20NEXT%0A%20%20ANCH%20--%3E%20NEXT%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,[a("三条不坍缩条件切断坍缩链的不同环节：累积式（Gerstgrasser 等 2024，含证明：替换式才坍缩，累积式即使加入合成数据也平稳）切断了真实分布信息的丢失；回混约一成真实数据即可大幅推迟坍缩（Shumailov 原文实验口径），相当于每代重新注入尾部样本；质量过滤减缓收缩速率，但不改变方向。落成工程口径：监测上，每代在真实 held-out 上看分布尾部指标——稀有 n-gram 覆盖率、长尾题型通过率、生成熵，不看平均分，平均分最后才动；结构上，回路必须带过滤器（上一课仪表加质量筛选），必须有真实数据锚（真实题、真实文本按固定比例回混），数据湖不删历史；比例上，合成占比在无独立真实探针验证时应设硬上限——"),e("a",{href:"/llm/textbook-synthetic"},"教科书式合成"),a("课的 \\(w_{\\mathrm{syn}}\\) 结论在闭环场景下更严。")],-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"每代是「采样—再拟合」两步：拟合对低密度区域的误差最大，采样又按模型概率加权——尾部本来样本就少，拟合误差在那里被放大，于是收缩从尾部开始、向中心推进。这解释了为什么监测尾部而不是均值：尾部是收缩的先行量，均值是滞后量。上一课的新颖度仪表与生成熵监测的正是这个损失——熵下降与新颖占比下滑先于平均指标恶化。三条不坍缩条件的共同点是把「生产数据的分布」与「模型自己的输出」重新锚定：累积式锚在历史，回混锚在真实语料，过滤则只是拖慢，不提供新信息。",-1)),(l(),t(s,null,{default:B(()=>[o(A,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E4%B8%8A%E4%B8%80%E4%BB%A3%E6%A8%A1%E5%9E%8B%E5%88%86%E5%B8%83%22%5D%20--%3E%20S%5B%22%E6%8C%89%E6%A6%82%E7%8E%87%E9%87%87%E6%A0%B7%EF%BC%9A%E5%B0%BE%E9%83%A8%E6%A0%B7%E6%9C%AC%E6%9C%AC%E6%9D%A5%E5%B0%B1%E5%B0%91%22%5D%0A%20%20S%20--%3E%20F%5B%22%E5%86%8D%E6%8B%9F%E5%90%88%EF%BC%9A%E4%BD%8E%E5%AF%86%E5%BA%A6%E5%8C%BA%E8%AF%AF%E5%B7%AE%E8%A2%AB%E6%94%BE%E5%A4%A7%22%5D%0A%20%20F%20--%3E%20N%5B%22%E4%B8%8B%E4%B8%80%E4%BB%A3%E5%88%86%E5%B8%83%EF%BC%9A%E5%B0%BE%E9%83%A8%E6%9B%B4%E7%A8%80%22%5D%0A%20%20N%20--%3E%7C%22%E6%97%A0%E5%9B%9E%E6%B7%B7%EF%BC%8C%E5%BE%AA%E7%8E%AF%E7%BB%A7%E7%BB%AD%22%7C%20S%0A%20%20N%20--%3E%7C%22%E6%AF%8F%E4%BB%A3%E6%8E%BA%E4%B8%80%E6%88%90%E7%9C%9F%E5%AE%9E%E6%95%B0%E6%8D%AE%22%7C%20A%5B%22%E5%B0%BE%E9%83%A8%E8%A2%AB%E9%87%8D%E6%96%B0%E6%B3%A8%E5%85%A5%EF%BC%8C%E6%94%B6%E7%BC%A9%E8%A2%AB%E9%94%9A%E4%BD%8F%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">数字实例：设某罕见表达在真实数据里占 0.1%，而模型对它的采样概率只有 0.05%——替换式递归下，下一代的训练集里它出现得更少，拟合后概率再降。按每代打对折的速率，五六代后这个表达就等于消失了；高频表达则几乎无损。这就是「尾部先丢」的算术。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>坍缩实证多在受控设定（高斯、小语料、数字级任务）与替换式递归；大模型工程里回路通常带过滤、回混与外部题源，观测到的多为「分布变窄」而非「崩溃」。反过来，没观察到崩溃不等于收缩没发生——尾部能力（罕见解法、长尾实体）的退化先于平均指标。<span class="marginnote">常见误区：初学者容易用「我们递归训练了好几代，基准分没掉」反驳坍缩。实际上平均分是滞后量，最先坏掉的是长尾——应去看稀有 n-gram 覆盖率与长尾题型通过率，而不是平均准确率。</span>RL 侧还有另一种熵收缩（<a href="/llm/entropy-collapse">熵塌缩</a>课）：那是策略熵在优化压力下的塌缩，不是数据测度的收缩，不要混用。分布即使不坍缩，也已被验证器与过滤器的支撑截断——截断点选在哪，是下一课验证器瓶颈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>替换式递归自食：尾部先丢、熵收缩、数代内近乎不可逆（Shumailov 等，Nature 2024）。</li><li>不坍缩三条件：累积式数据、真实数据回混（约一成即可大幅推迟）、质量过滤减缓。</li><li>监测尾部指标不看平均分；新颖度与熵是先行量。</li><li>熵塌缩是策略熵现象，与数据坍缩机制不同，不混用。</li><li>出处：Shumailov 等 Nature 2024；Alemohammad 等自消费生成模型；Gerstgrasser 等 2024 累积式不坍缩。</li></ul>',5))])}const _=i(m,[["render",C]]);export{f as __pageData,_ as default};
